/**
 * Der Vertrag für alles, was in einer Warteschlange stehen darf.
 * Ein Interface enthält nur Methodenköpfe, keine Rümpfe.
 */
public interface DatenElement {
   // TODO 3a (Aufgabe 3): Methodenkopf für gibSchluesselwert() eintragen

}

/**
 * Die Daten einer Patientin oder eines Patienten (aus Station 1.1).
 * TODO 3b (Aufgabe 3): Patient soll das Interface DatenElement implementieren.
 */
public class Patient {
   private String name;
   private String beschwerden;

   public Patient(String name, String beschwerden) {
      this.name = name;
      this.beschwerden = beschwerden;
   }

   public String getName() {
      return name;
   }

   public String getBeschwerden() {
      return beschwerden;
   }
}

/**
 * Ein Taxi am Taxistand.
 * TODO 4 (Aufgabe 4): Taxi soll das Interface DatenElement implementieren.
 * Schlüsselwert eines Taxis: "Taxi " und seine Nummer, z. B. "Taxi 12".
 */
public class Taxi {
   private int nummer;
   private String fahrer;

   public Taxi(int nummer, String fahrer) {
      this.nummer = nummer;
      this.fahrer = fahrer;
   }

   public int getNummer() {
      return nummer;
   }

   public String getFahrer() {
      return fahrer;
   }
}

/**
 * Ein Knoten der Warteschlange (aus Station 1.1).
 * TODO 3c (Aufgabe 3): Der Knoten soll beliebige DatenElemente tragen,
 * nicht nur Patienten. Ersetze dazu jedes "Patient" durch "DatenElement".
 */
public class Knoten {
   private Patient daten;
   private Knoten nachfolger;

   public Knoten(Patient daten) {
      this.daten = daten;
      nachfolger = null;
   }

   public Patient getDaten() {
      return daten;
   }

   public Knoten getNachfolger() {
      return nachfolger;
   }

   public void setNachfolger(Knoten nachfolger) {
      this.nachfolger = nachfolger;
   }
}

/**
 * Warteschlange (Queue) aus Station 1.1 – bisher nur für Patienten.
 * TODO 3d (Aufgabe 3): Die Warteschlange soll beliebige DatenElemente
 * verwalten. Ersetze jedes "Patient" durch "DatenElement" und passe
 * ausgeben() an.
 */
public class Warteschlange {
   private Knoten anfang;   // erster Knoten: kommt als Nächstes dran
   private Knoten ende;     // letzter Knoten: hier wird angehängt

   public Warteschlange() {
      anfang = null;
      ende = null;
   }

   public boolean isEmpty() {
      return anfang == null;
   }

   public boolean add(Patient p) {
      Knoten neu = new Knoten(p);
      if (isEmpty()) {
         anfang = neu;
         ende = neu;
      } else {
         ende.setNachfolger(neu);
         ende = neu;
      }
      return true;
   }

   public Patient poll() {
      if (isEmpty()) {
         return null;
      } else {
         Patient p = anfang.getDaten();
         anfang = anfang.getNachfolger();
         if (anfang == null) {
            ende = null;
         }
         return p;
      }
   }

   public Patient peek() {
      if (isEmpty()) {
         return null;
      } else {
         return anfang.getDaten();
      }
   }

   public void ausgeben() {
      Knoten aktuell = anfang;
      int platz = 1;
      while (aktuell != null) {
         println("  " + platz + ". " + aktuell.getDaten().getName());
         aktuell = aktuell.getNachfolger();
         platz++;
      }
   }
}
